    if (blockpos != null) {
        compound.putInt("DX", blockpos.getX());
        compound.putInt("DY", blockpos.getY());
        compound.putInt("DZ", blockpos.getZ());
    }
    if (this.getSisterId() != null) {
        compound.putUUID("SisterUUID", this.getSisterId());
    }
    if(this.exitDimension != null){
        ResourceLocation.CODEC.encodeStart(NbtOps.INSTANCE, this.exitDimension.location()).resultOrPartial(AlexsMobs.LOGGER::error).ifPresent((p_241148_1_) -> {
            compound.put("ExitDimension", p_241148_1_);
        });
    }

}

public Entity getSister() {
    UUID id = getSisterId();
    if (id != null && !this.level().isClientSide) {
        return ((ServerLevel) level()).getEntity(id);
    }
    return null;
}

private void initKangarooInventory() {
    SimpleContainer animalchest = this.kangarooInventory;
    this.kangarooInventory = new SimpleContainer(9) {
        public void stopOpen(Player player) {
            EntityKangaroo.this.entityData.set(POUCH_TICK, 10);
            EntityKangaroo.this.resetKangarooSlots();
        }

        public boolean stillValid(Player player) {
            return EntityKangaroo.this.isAlive() && !EntityKangaroo.this.isInsidePortal;
        }
    };
    kangarooInventory.addListener(this);
    if (animalchest != null) {
        int i = Math.min(animalchest.getContainerSize(), this.kangarooInventory.getContainerSize());
        for (int j = 0; j < i; ++j) {
            ItemStack itemstack = animalchest.getItem(j);
            if (!itemstack.isEmpty()) {
                this.kangarooInventory.setItem(j, itemstack.copy());
            }
        }
        resetKangarooSlots();
    }

}

public void load(CompoundTag tag) {
    super.load(tag);
    totalTransmuteCount = tag.getInt("TotalCount");
    ListTag list = new ListTag();
    for(Map.Entry<UUID, TransmutationData> entry : playerToData.entrySet()){
        CompoundTag innerTag = new CompoundTag();
        innerTag.putUUID("UUID", entry.getKey());
        innerTag.put("TransmutationData", entry.getValue().saveAsNBT());
        list.add(innerTag);
    }
    tag.put("PlayerTransmutationData", list);
    for(int i = 0; i < 3; i++){
        if(tag.contains("Possibility" + i)){
            possiblities[i] = ItemStack.of(tag.getCompound("Possiblity" + i));
        }
    }

}

protected void saveAdditional(CompoundTag tag) {
    super.saveAdditional(tag);
    tag.putInt("TotalCount", totalTransmuteCount);
    ListTag list = tag.getList("PlayerTransmutationData", 10);
    if(!list.isEmpty()){
        for(int i = 0; i < list.size(); ++i) {
            CompoundTag compoundtag = list.getCompound(i);
            UUID uuid = compoundtag.getUUID("UUID");
            if(uuid != null){
                playerToData.put(uuid, TransmutationData.fromNBT(compoundtag.getCompound("TransmutationData")));
            }
        }
    }
    for(int i = 0; i < 3; i++){
        if(possiblities[i] != null && !possiblities[i].isEmpty()){
            tag.put("Possiblity" + i, possiblities[i].serializeNBT());
        }
    }
}

public void postTransmute(Player player, ItemStack from, ItemStack to){
    TransmutationData data;
    if(playerToData.containsKey(player.getUUID())){
        data = playerToData.get(player.getUUID());
    }else{
        data = new TransmutationData();
    }
    data.onTransmuteItem(from, to);
    playerToData.put(player.getUUID(), data);
    totalTransmuteCount += from.getCount();
    if(player instanceof ServerPlayer && totalTransmuteCount >= 1000){
        AMAdvancementTriggerRegistry.TRANSMUTE_1000_ITEMS.trigger((ServerPlayer)player);
    }
    setRerollPlayerUUID(player.getUUID());
}
